-- The TW3SE Lua API (w3.*), for the editor. Hand-written from docs/LUA.md; the game's classes are in w3.lua
-- (generated by tools/gen_types.py). Put both into a folder your editor's Lua extension reads (see README.md).
---@meta

---A position: a game Vector, or a table with X, Y, Z (or {x, y, z}).
---@alias w3.pos Vector|{X: number, Y: number, Z: number}|number[]
---A colour as 0xRRGGBBAA.
---@alias w3.colour integer
---A handle w3.on_tick, w3.every, w3.after, w3.watch and the other on_ functions give back.
---@alias w3.handle integer

---@class w3
w3 = {}

-- ----------------------------------------------------------------------------------------------------------------
-- Objects

---The player, or nil in the main menu.
---@return W3PlayerWitcher|nil
function w3.player() end

---A global of the game's scripts: theGame, thePlayer, theCamera, theSound, theInput ...
---@param name string
---@return any
function w3.global(name) end

---The class name of an object.
---@param obj any
---@return string
function w3.classof(obj) end

---True while the game object behind the value is alive.
---@param obj any
---@return boolean
function w3.valid(obj) end

---A new object of a scripted or engine class, the way `new <class> in <parent>` makes it (parent: theGame).
---@param className string
---@param parent? any
---@return any
function w3.new(className, parent) end

---Copies every field it can from source into target (same class); returns the fields it left out.
---@param target any
---@param source any
---@return string[]
function w3.copy(target, source) end

---A resource by its depot path (a template, a mesh ...), loaded.
---@param path string
---@return any
function w3.load(path) end

---An object at an address, seen as a class.
---@param address integer
---@param className? string
---@return any
function w3.object(address, className) end

-- ----------------------------------------------------------------------------------------------------------------
-- Calling functions and hooks

---Calls a global function (native or WitcherScript) by name. Out values and arrays come back as extra values.
---@param name string
---@param ... any
---@return any ...
function w3.call(name, ...) end
---Gives a native without an import line its signature: "int, out array<name>, optional float -> bool".
---"Class.Name" for a method. Refused for a function the scripts declare.
---@param name string
---@param signature string
---@return boolean
function w3.declare(name, signature) end
---Runs fn before an engine function of the address list: a[1]..a[4] its register arguments, a[5]..a[8] from the
---stack, a.name. A returned table replaces the four registers. Main thread only.
---@param name string
---@param fn fun(a: table): table?
---@return integer
function w3.engine_hook(name, fn) end
---@param id integer
---@return boolean
function w3.engine_unhook(id) end
---@return {name: string, calls: integer, handlers: integer}[]
function w3.engine_hooks() end
---An enum WitcherScript uses by its name and value names (from a natives file: before the scripts compile).
---@param name string
---@param values table<string, integer>
---@return boolean
function w3.new_enum(name, values) end
---The default values of a class's fields (its parents' too), from a fresh object.
---@param className string
---@return table<string, any>
function w3.defaults(className) end
---Lets an object w3.new made go at the next tick; true when no other Lua value holds it.
---@param obj any
---@return boolean
function w3.discard(obj) end

---Puts a handler on a function or event: fn(self, args, orig). Returns a handle for w3.unhook.
---Two forms: w3.hook(className, name, fn [, priority]) for a method, w3.hook(name, fn [, priority]) for a global.
---@param classOrName string
---@param nameOrFn string|fun(self: any, args: any[], orig: fun(): any): any
---@param fn? fun(self: any, args: any[], orig: fun(): any): any
---@param priority? integer
---@return integer
function w3.hook(classOrName, nameOrFn, fn, priority) end

---Takes a hook off.
---@param handle integer
function w3.unhook(handle) end

---Puts a handler on a vtable slot of an object's class: fn(self, a, orig), a = the raw arguments.
---@param obj any
---@param slot integer
---@param fn fun(self: any, a: table, orig: fun(): integer, number): any
---@return integer
function w3.vhook(obj, slot, fn) end

---Takes a virtual hook off.
---@param handle integer
function w3.vunhook(handle) end

---The function in a vtable slot, as an offset in witcher3.exe.
---@param obj any
---@param slot integer
---@return integer
function w3.vslot(obj, slot) end

---Gives WitcherScript a new function; the script's `import function` line sets parameters and return.
---"Class.Name" makes a method of a native class (`@addMethod(Class) import function ...`); fn gets the object first.
---@param name string
---@param fn function
function w3.native(name, fn) end

---Runs console commands (several with "\x1f" between them). Returns true, or false and the error.
---@param cmd string
---@return boolean ok
---@return string? err
function w3.exec(cmd) end

---The WitcherScript functions running now, innermost first.
---@return {name: string, file: string, line: integer}[]
function w3.script_stack() end

---Runs fn(info) each time the game is about to run that line of a script file.
---@param file string
---@param line integer
---@param fn fun(info: {file: string, line: integer, name: string, self: any, vars: table, set: fun(name: string, value: any)})
---@return integer
function w3.on_line(file, line, fn) end

---Ends a line watch.
---@param handle integer
function w3.off_line(handle) end

-- ----------------------------------------------------------------------------------------------------------------
-- Looking things up

---Every pre-placed entity currently loaded, optionally of a class.
---@param className? string
---@return CEntity[]
function w3.entities(className) end

---Every live object of a class (spawned ones, managers, quest objects too).
---@param className string
---@param limit? integer
---@param withTemplates? boolean
---@return any[]
function w3.all(className, limit, withTemplates) end

---Loaded entities near the player: w3.near(radius [, class]), or near a point: w3.near(pos, radius [, class]).
---@param radiusOrPos number|w3.pos
---@param radiusOrClass? number|string
---@param className? string
---@return CEntity[]
function w3.near(radiusOrPos, radiusOrClass, className) end

---Entities with a tag.
---@param tag string
---@return CEntity[]
function w3.by_tag(tag) end

---The entity with a pre-placed GUID, or nil.
---@param guid string
---@return CEntity|nil
function w3.by_guid(guid) end

---An entity's pre-placed GUID ("aaaaaaaa-..."), or nil for a run-time object.
---@param entity CEntity
---@return string|nil
function w3.guid(entity) end

---Names of the classes and enums that contain the text.
---@param text string
---@return string[]
function w3.find(text) end

---A class: {name, parent, size, fields = {...}, methods = {...}}.
---@param name string
---@return table
function w3.class(name) end

---The fields of an object, with type and offset.
---@param obj any
---@return table
function w3.fields(obj) end

---The methods of an object's class.
---@param obj any
---@return string[]
function w3.methods(obj) end

---All fields of an object as text (name, type, value), optionally filtered by name.
---@param obj any
---@param filter? string
---@return string
function w3.dump(obj, filter) end

---An enum (or bitfield) as value name -> number.
---@param name string
---@return table<string, integer>
function w3.enum(name) end

---The point d metres in front of the player, on the ground.
---@param d number
---@return Vector
function w3.ahead(d) end

-- ----------------------------------------------------------------------------------------------------------------
-- Game events

---@alias w3.event "hit"|"death"|"item_added"|"item_removed"|"consume"|"level_up"|"sign"|"combat_start"|"combat_end"|"fact"|"spawn"|"scene_start"|"scene_end"|"quest"|"world"|"hour"|"load"|"save"

---Runs fn(e) each time the event happens; e holds what belongs to it (see docs/LUA.md, "Game events").
---hit: victim, attacker, damage, action; death: victim, killer, action; item_added: owner, player, name, count, ids;
---item_removed: owner, player, name, id, count; consume: name, id, potion; level_up: level; sign: sign; combat_start,
---combat_end: player; fact: name, value; spawn: npc; quest: title, status, old; world: path, old; hour: hour, day.
---@param name w3.event
---@param fn fun(e: table)
---@return integer
function w3.on(name, fn) end

---Stops a function of w3.on.
---@param handle integer
function w3.off(handle) end

---The names w3.on knows.
---@return string[]
function w3.events() end

-- ----------------------------------------------------------------------------------------------------------------
-- Every frame, timers, keys

---Runs fn once per game tick.
---@param fn fun()
---@return w3.handle
function w3.on_tick(fn) end

---Stops a function of on_tick, every, after or watch.
---@param handle w3.handle
function w3.off_tick(handle) end

---Runs fn every s seconds.
---@param s number
---@param fn fun()
---@return w3.handle
function w3.every(s, fn) end

---Runs fn once, s seconds later.
---@param s number
---@param fn fun()
---@return w3.handle
function w3.after(s, fn) end

---Runs fn(new, old) when a field of an object changes.
---@param obj any
---@param field string
---@param fn fun(new: any, old: any)
---@return w3.handle
function w3.watch(obj, field, fn) end

---Runs fn as a sequence that can wait (w3.wait, w3.wait_frames, a latent call's :wait()).
---@param fn fun()
function w3.run(fn) end

---Inside w3.run: waits s seconds.
---@param s number
function w3.wait(s) end

---Inside w3.run: waits n frames.
---@param n integer
function w3.wait_frames(n) end

---Inside w3.run: waits until fn() is true (at most timeout seconds).
---@param fn fun(): boolean
---@param timeout? number
---@return boolean
function w3.wait_until(fn, timeout) end

---Runs fn after every live reload of WitcherScript.
---@param fn fun()
---@return w3.handle
function w3.on_reload(fn) end

---@param handle w3.handle
function w3.off_reload(handle) end

---Runs fn once each time the key goes down ("F6", "Ctrl+Shift+K", "Mouse4", "0x70", "Pad_A", "Pad_LB+Pad_Y").
---Keyboard modifiers have to match; controller buttons before the + have to be held.
---@param key string|integer
---@param fn fun()
---@return w3.handle
function w3.on_key(key, fn) end

---@param handle w3.handle
function w3.off_key(handle) end

---True while the key is held.
---@param key string|integer
---@return boolean
function w3.key_down(key) end

-- ----------------------------------------------------------------------------------------------------------------
-- Data that goes with the save, files, settings

---This mod's table for the current save (outside a mod it needs a name).
---@param name? string
---@return table
function w3.saved(name) end

---A table of the mod's that stays across every save and new game (tw3se\store\<name>.lua, written within 2 s).
---@param name? string
---@return table
function w3.store(name) end

---Runs fn after a save loaded or a new game started.
---@param fn fun()
---@return w3.handle
function w3.on_load(fn) end

---@param handle w3.handle
function w3.off_load(handle) end

---Runs fn right before the saved tables are written.
---@param fn fun()
---@return w3.handle
function w3.on_save(fn) end

---@param handle w3.handle
function w3.off_save(handle) end

---A setting of the mod in the TW3SE Menu.
---@class w3.setting
---@field key? string
---@field type? "bool"|"slider"|"number"|"choice"|"text"|"key"|"header"|"button"
---@field label? string|table<string, string> a text, or one per language ({EN = ..., DE = ...})
---@field default? any
---@field tip? string|table<string, string>
---@field min? number
---@field max? number
---@field int? boolean
---@field items? string[]
---@field run? fun()

---@class w3.modspec
---@field name string
---@field tw3se? string The TW3SE version the mod needs ("1.2.0"); older stops the mod with the reason
---@field version? string
---@field author? string
---@field description? string|table<string, string>
---@field settings? w3.setting[]
---@field on_change? fun(key: string, value: any, old: any)
---@field game_menu? boolean false: no page in the game's Options > Mods (checkboxes, sliders and choices go there)
---@field tab? fun()

---Puts the mod into the TW3SE Menu with its settings. cfg.<key> reads and sets one, cfg.reset([key]).
---@param spec w3.modspec
---@return table
function w3.mod(spec) end

---The mods w3.mod registered.
---@return table[]
function w3.mods() end

---What another mod's init.lua returns (true for nothing); loads it first. The mod that asks loads again after it.
---@param name string the other mod's folder ("modWolfKit")
---@return any
function w3.use(name) end

---The game's text language and voice language as its scripts name them ("DE", "EN").
---@return string text, string voice
function w3.lang() end

---A text by language ({EN = "Wolf level", DE = "Wolfsstufe"}): the game's language, else EN, else any. A string
---stays as it is.
---@param t string|table<string, string>
---@return string
function w3.tr(t) end

---TW3SE's version as text and as three numbers ("1.2.0", 1, 2, 0).
---@return string, integer, integer, integer
function w3.version() end

---TW3SE's folder (bin\x64_dx12\tw3se), UTF-8.
---@return string
function w3.dir() end

---The bug report as text (also written to tw3se\out\report.txt).
---@return string
function w3.report() end

---The time each mod spent: a list of {mod, kind, calls, ms, max, per_tick} and the number of ticks.
---@param reset? boolean
---@return table[], integer
function w3.profile(reset) end

---The WitcherScript profiler: "on" counts, "off" stops, "reset" starts again. Returns the functions by their own
---time, the seconds it counted, and whether it counts.
---@param cmd? "on"|"off"|"reset"
---@return {fn: string, file: string, mod: string, calls: integer, own: number, whole: number}[], number, boolean
function w3.script_profile(cmd) end

---An engine setting: w3.config(group, name) reads it, w3.config(group, name, value) sets it.
---@param group string
---@param name string
---@param value? any
---@return any
function w3.config(group, name, value) end

---The engine settings whose path contains the text: {path, type}.
---@param filter? string
---@return {path: string, type: string}[]
function w3.config_list(filter) end

